// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Exchange an email and a password for a session
	// (POST /admin/v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Revoke a refresh token
	// (POST /admin/v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Whoami Who this token authenticates as
	// (GET /admin/v1/auth/me)
	Whoami(ctx context.Context, request WhoamiRequestObject) (WhoamiResponseObject, error)
	// RefreshSession Rotate a refresh token into a new session
	// (POST /admin/v1/auth/refresh)
	RefreshSession(ctx context.Context, request RefreshSessionRequestObject) (RefreshSessionResponseObject, error)
	// RevokeAPIKey Revoke a key
	// (DELETE /admin/v1/keys/{key})
	RevokeAPIKey(ctx context.Context, request RevokeAPIKeyRequestObject) (RevokeAPIKeyResponseObject, error)
	// GetAPIKey Read one key
	// (GET /admin/v1/keys/{key})
	GetAPIKey(ctx context.Context, request GetAPIKeyRequestObject) (GetAPIKeyResponseObject, error)
	// UpdateAPIKey Replace a key's model allowlist
	// (PATCH /admin/v1/keys/{key})
	UpdateAPIKey(ctx context.Context, request UpdateAPIKeyRequestObject) (UpdateAPIKeyResponseObject, error)
	// GetRequest Why did this request go where it did?
	// (GET /admin/v1/requests/{decision_id})
	GetRequest(ctx context.Context, request GetRequestRequestObject) (GetRequestResponseObject, error)
	// ListTenants List tenants
	// (GET /admin/v1/tenants)
	ListTenants(ctx context.Context, request ListTenantsRequestObject) (ListTenantsResponseObject, error)
	// CreateTenant Create a tenant
	// (POST /admin/v1/tenants)
	CreateTenant(ctx context.Context, request CreateTenantRequestObject) (CreateTenantResponseObject, error)
	// DisableTenant Disable a tenant
	// (DELETE /admin/v1/tenants/{tenant})
	DisableTenant(ctx context.Context, request DisableTenantRequestObject) (DisableTenantResponseObject, error)
	// GetTenant Read one tenant
	// (GET /admin/v1/tenants/{tenant})
	GetTenant(ctx context.Context, request GetTenantRequestObject) (GetTenantResponseObject, error)
	// UpdateTenant Change a tenant's name and/or metadata
	// (PATCH /admin/v1/tenants/{tenant})
	UpdateTenant(ctx context.Context, request UpdateTenantRequestObject) (UpdateTenantResponseObject, error)
	// ListAudit A tenant's audit events, newest first
	// (GET /admin/v1/tenants/{tenant}/audit)
	ListAudit(ctx context.Context, request ListAuditRequestObject) (ListAuditResponseObject, error)
	// EnableTenant Re-enable a disabled tenant
	// (POST /admin/v1/tenants/{tenant}/enable)
	EnableTenant(ctx context.Context, request EnableTenantRequestObject) (EnableTenantResponseObject, error)
	// ListAPIKeys List a tenant's keys, revoked ones included
	// (GET /admin/v1/tenants/{tenant}/keys)
	ListAPIKeys(ctx context.Context, request ListAPIKeysRequestObject) (ListAPIKeysResponseObject, error)
	// CreateAPIKey Mint an API key
	// (POST /admin/v1/tenants/{tenant}/keys)
	CreateAPIKey(ctx context.Context, request CreateAPIKeyRequestObject) (CreateAPIKeyResponseObject, error)
	// ListQuotas The tenant's whole quota set
	// (GET /admin/v1/tenants/{tenant}/quotas)
	ListQuotas(ctx context.Context, request ListQuotasRequestObject) (ListQuotasResponseObject, error)
	// ReplaceQuotas Replace the tenant's whole quota set
	// (PUT /admin/v1/tenants/{tenant}/quotas)
	ReplaceQuotas(ctx context.Context, request ReplaceQuotasRequestObject) (ReplaceQuotasResponseObject, error)
	// DeleteQuota Remove one window's quota
	// (DELETE /admin/v1/tenants/{tenant}/quotas/{window})
	DeleteQuota(ctx context.Context, request DeleteQuotaRequestObject) (DeleteQuotaResponseObject, error)
	// GetQuota One window's quota
	// (GET /admin/v1/tenants/{tenant}/quotas/{window})
	GetQuota(ctx context.Context, request GetQuotaRequestObject) (GetQuotaResponseObject, error)
	// PutQuota Set one window's quota, leaving the others alone
	// (PUT /admin/v1/tenants/{tenant}/quotas/{window})
	PutQuota(ctx context.Context, request PutQuotaRequestObject) (PutQuotaResponseObject, error)
	// GetUsage What did this tenant spend, and on what?
	// (GET /admin/v1/tenants/{tenant}/usage)
	GetUsage(ctx context.Context, request GetUsageRequestObject) (GetUsageResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Login operation middleware
func (sh *strictHandler) Login(w http.ResponseWriter, r *http.Request) {
	var request LoginRequestObject

	var body LoginJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Login(ctx, request.(LoginRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Login")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(LoginResponseObject); ok {
		if err := validResponse.VisitLoginResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

